import { Data, Effect } from "effect"

export interface Shipment {
  readonly id: string
  readonly depot: string
  readonly status: "packing" | "ready" | "dispatched"
  readonly cartonCount: number
}

export class ShipmentMissing extends Data.TaggedError("ShipmentMissing")<{
  readonly shipmentId: string
}> {}

export class ShipmentNotReady extends Data.TaggedError("ShipmentNotReady")<{
  readonly shipmentId: string
  readonly depot: string
  readonly status: Shipment["status"]
}> {}

export interface ShipmentRepository {
  readonly find: (id: string) => Effect.Effect<Shipment, ShipmentMissing>
}

export interface DispatchTicket {
  readonly shipmentId: string
  readonly depot: string
  readonly cartonCount: number
}

export const buildDispatchTicket = (
  repository: ShipmentRepository,
  shipmentId: string
): Effect.Effect<DispatchTicket, ShipmentMissing | ShipmentNotReady> =>
  Effect.gen(function*() {
    const shipment = yield* repository.find(shipmentId).pipe(
      Effect.filterOrFail(
        (shipment) => shipment.status === "ready",
        (shipment) => new ShipmentNotReady({
          shipmentId: shipment.id,
          depot: shipment.depot,
          status: shipment.status
        })
      )
    )

    return {
      shipmentId: shipment.id,
      depot: shipment.depot,
      cartonCount: shipment.cartonCount
    }
  })
